def norm(t):
    """Voller Schlüssel inklusive Klammertext: 'EAC (typical)' und 'EAC (atypical)' bleiben getrennt."""
    return re.sub(r"[^a-z0-9]+", " ", t.lower()).strip()


def base(t):
    return norm(re.sub(r"\(.*?\)", " ", t))


def hint_index():
    full, bases = {}, {}
    for term, (kurz, eb) in H.items():
        h = {"hint_short": kurz, "hint_eb": eb}
        full[norm(term)] = h
        bases.setdefault(base(term), []).append(h)
    return full, {k: v[0] for k, v in bases.items() if len(v) == 1}      # Basisname nur, wenn er eindeutig ist


def attach(cards):
    """Hängt Merkhilfen an Karten (Dicts) an: erst voller Name, dann eindeutiger Name ohne Klammern; liefert die Trefferzahl."""
    full, uniq = hint_index()
    n = 0
    for c in cards:
        t = c.get("term", "")
        h = full.get(norm(t)) or uniq.get(base(t))
        if h:
            c.update(h)
            n += 1
    return n


if __name__ == "__main__":
    root = os.path.normpath(os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
    cards = []
    for f in ("glossary_pmp.json", "glossary_pmp_pmi.json"):
        p = os.path.join(root, "data", f)
        cards += json.load(open(p, encoding="utf-8")) if os.path.exists(p) else []
    n = attach(cards)
    full, uniq = hint_index()
    hit = {norm(c["term"]) for c in cards if norm(c["term"]) in full or base(c["term"]) in uniq} | {base(c["term"]) for c in cards if base(c["term"]) in uniq}
    miss = [t for t in H if norm(t) not in hit and base(t) not in hit]
    print(len(H), "Hinweise |", n, "von", len(cards), "Karten bekommen eine Merkhilfe | Schlüssel ohne Karte:", miss)
